CREATE TABLE users (id UUID PRIMARY KEY, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, name VARCHAR(160) NOT NULL, phone VARCHAR(30), role VARCHAR(30) NOT NULL, active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), last_login_at TIMESTAMPTZ);
CREATE TABLE categories (id UUID PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, slug VARCHAR(140) NOT NULL UNIQUE, description TEXT, active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE products (id UUID PRIMARY KEY, name VARCHAR(200) NOT NULL, slug VARCHAR(220) NOT NULL UNIQUE, sku VARCHAR(80) NOT NULL UNIQUE, description TEXT, price NUMERIC(12,2) NOT NULL CHECK(price >= 0), discount_price NUMERIC(12,2), status VARCHAR(30) NOT NULL, featured BOOLEAN NOT NULL DEFAULT false, category_id UUID REFERENCES categories(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE inventory (id UUID PRIMARY KEY, product_id UUID NOT NULL UNIQUE REFERENCES products(id), quantity INTEGER NOT NULL DEFAULT 0 CHECK(quantity >= 0), low_stock_threshold INTEGER NOT NULL DEFAULT 5 CHECK(low_stock_threshold >= 0), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE product_images (id UUID PRIMARY KEY, product_id UUID NOT NULL REFERENCES products(id) ON DELETE CASCADE, url TEXT NOT NULL, primary_image BOOLEAN NOT NULL DEFAULT false, display_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE orders (id UUID PRIMARY KEY, order_number VARCHAR(40) NOT NULL UNIQUE, customer_id UUID NOT NULL REFERENCES users(id), status VARCHAR(30) NOT NULL, subtotal NUMERIC(12,2) NOT NULL, shipping NUMERIC(12,2) NOT NULL DEFAULT 0, total NUMERIC(12,2) NOT NULL, recipient_name VARCHAR(160) NOT NULL, email VARCHAR(255) NOT NULL, phone VARCHAR(30), address_line TEXT NOT NULL, city VARCHAR(100) NOT NULL, state VARCHAR(100) NOT NULL, postal_code VARCHAR(30) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE order_items (id UUID PRIMARY KEY, order_id UUID NOT NULL REFERENCES orders(id) ON DELETE CASCADE, product_id UUID NOT NULL REFERENCES products(id), product_name VARCHAR(200) NOT NULL, sku VARCHAR(80) NOT NULL, unit_price NUMERIC(12,2) NOT NULL, quantity INTEGER NOT NULL CHECK(quantity > 0), line_total NUMERIC(12,2) NOT NULL);
CREATE TABLE inventory_transactions (id UUID PRIMARY KEY, product_id UUID NOT NULL REFERENCES products(id), actor_id UUID REFERENCES users(id), previous_quantity INTEGER NOT NULL, change_quantity INTEGER NOT NULL, new_quantity INTEGER NOT NULL, reason VARCHAR(255), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id UUID PRIMARY KEY, actor_id UUID REFERENCES users(id), action VARCHAR(80) NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_id UUID, description TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_products_category ON products(category_id); CREATE INDEX idx_orders_customer ON orders(customer_id); CREATE INDEX idx_audit_created ON audit_logs(created_at DESC);
